import json, subprocess, time
from datetime import datetime

# Config
AUTH = "gk_live_79414cc5d34021a6.f48b009c9ed9470d05fbec8f4ef919f4d657e7a15d91347a"
CLIENT_ID = "cli_a1b2c3d4e5f6789012345678abcdef90"
BASE_URL = "https://openapi.biji.com/open/api/v1/resource"

# KB topic_ids
KB_CHIP = "9YeBam0m"
KB_OPENCLAW = "G0P1Z51J"
KB_FAMILY = "EJX1r7bn"

# Keywords
CHIP_KW = ['芯片', '半导体', 'ecdn', 'ear', '出口管制', '封装', '测试', '良率', '供应商', '质量']
OPENCLAW_KW = ['openclaw', 'agent', 'skill', 'chatgpt', 'deepseek', 'claude', '大模型', 'ai工具']
FAMILY_KW = ['兮兮', '中考', '英语', '语文', '数学', '物理', '化学', '生物', '地理', '学习', '教育', '成绩', '考试', '错题', '青春期', '亲子']

SKIP_PREFIXES = ['🌱发芽日报', '📦每日备份报告', '每日复盘', '🦐发芽报告', 'OpenClaw每日备份报告']

API_CALLS = 0
IMPORTED = 0
SCANNED = 0

def api_call(method, path, data=None):
    global API_CALLS
    API_CALLS += 1
    # path already includes full path like /note/list?since_id=xxx
    url = f'{BASE_URL}{path}'
    cmd = ['curl', '-s', '-X', method, url,
           '-H', f'Authorization: {AUTH}',
           '-H', f'X-Client-ID: {CLIENT_ID}']
    if data:
        cmd += ['-H', 'Content-Type: application/json', '-d', json.dumps(data)]
    result = subprocess.run(cmd, capture_output=True, text=True)
    try:
        return json.loads(result.stdout)
    except:
        print(f"API call failed: {result.stdout[:200]}")
        return None

def should_skip(title):
    for p in SKIP_PREFIXES:
        if title.startswith(p):
            return True
    return False

def match_note(title, content, note_type):
    if note_type not in ['plain_text', 'ref']:
        return None
    title = title or ''
    content = content or ''
    full_text = (title + ' ' + content).lower()
    if not full_text.strip():
        return None
    if should_skip(title):
        return None
    for kw in CHIP_KW:
        if kw.lower() in full_text:
            return 'chip'
    for kw in OPENCLAW_KW:
        if kw.lower() in full_text:
            return 'openclaw'
    for kw in FAMILY_KW:
        if kw.lower() in full_text:
            return 'family'
    return None

def get_detail(note_id):
    return api_call('GET', f'/note/detail?id={note_id}')

def batch_add(topic_id, note_ids):
    result = api_call('POST', '/knowledge/note/batch-add', {
        'topic_id': topic_id,
        'note_ids': note_ids
    })
    if result and result.get('success'):
        return result['data']['success_count']
    print(f"batch_add failed: {result}")
    return 0

def main():
    global IMPORTED, SCANNED

    cursor = 1855994895983210705
    max_api_calls = 450

    kb_chip_ids = []
    kb_openclaw_ids = []
    kb_family_ids = []

    print(f"[{datetime.now().strftime('%H:%M:%S')}] Starting scan from cursor {cursor}")

    batch_num = 0
    while API_CALLS < max_api_calls:
        batch_num += 1
        print(f"\n=== Batch {batch_num} (API calls so far: {API_CALLS}) ===")

        resp = api_call('GET', f'/note/list?since_id={cursor}')
        if not resp or not resp.get('success'):
            print(f"List API failed: {resp}")
            break

        data = resp.get('data', {})
        notes = data.get('notes', [])
        has_more = data.get('has_more', False)
        next_cursor = data.get('next_cursor')

        if not notes:
            print("No more notes!")
            break

        print(f"Got {len(notes)} notes, has_more={has_more}, next={next_cursor}")
        SCANNED += len(notes)

        for n in notes:
            note_id = n['id']
            title = n.get('title', '') or ''
            content = n.get('content', '') or ''
            note_type = n.get('note_type', '')

            kb = match_note(title, content, note_type)
            if kb:
                if note_type in ['plain_text', 'ref'] and (title or content):
                    if kb == 'chip':
                        kb_chip_ids.append(note_id)
                    elif kb == 'openclaw':
                        kb_openclaw_ids.append(note_id)
                    else:
                        kb_family_ids.append(note_id)
                    print(f"  [+{kb.upper()}] {title[:50] or '(no title)'}")
                else:
                    # link/img_text - need detail for full content
                    if API_CALLS >= max_api_calls - 5:
                        print(f"  Skipping detail (near limit)")
                        continue
                    detail = get_detail(note_id)
                    if detail and detail.get('success'):
                        nd = detail.get('data', {}).get('note', {})
                        dtitle = nd.get('title', '') or ''
                        dcontent = nd.get('content', '') or ''
                        dref = nd.get('ref_content', '') or ''
                        full = dcontent + ' ' + dref
                        dk = match_note(dtitle, full, note_type)
                        if dk:
                            if dk == 'chip':
                                kb_chip_ids.append(note_id)
                            elif dk == 'openclaw':
                                kb_openclaw_ids.append(note_id)
                            else:
                                kb_family_ids.append(note_id)
                            print(f"  [+{dk.upper()}] {dtitle[:50] or '(no title)'}")

        if not has_more or not next_cursor:
            print("Last page reached")
            break
        cursor = next_cursor

    print(f"\n=== Scan Done ===")
    print(f"Scanned: {SCANNED}, API calls: {API_CALLS}")
    print(f"Chip: {len(kb_chip_ids)}, OpenClaw: {len(kb_openclaw_ids)}, Family: {len(kb_family_ids)}")

    # Deduplicate
    def dedup(lst):
        seen = set()
        r = []
        for x in lst:
            if x not in seen:
                seen.add(x)
                r.append(x)
        return r

    kb_chip_ids = dedup(kb_chip_ids)
    kb_openclaw_ids = dedup(kb_openclaw_ids)
    kb_family_ids = dedup(kb_family_ids)

    # Batch add (max 50 writes total)
    total_to_add = len(kb_chip_ids) + len(kb_openclaw_ids) + len(kb_family_ids)
    print(f"Total to add: {total_to_add}")

    def add_chunk(tid, ids, name):
        global IMPORTED
        for i in range(0, len(ids), 20):
            chunk = ids[i:i+20]
            cnt = batch_add(tid, chunk)
            IMPORTED += cnt
            print(f"  {name}: +{cnt}")

    if kb_chip_ids:
        add_chunk(KB_CHIP, kb_chip_ids, 'CHIP')
    if kb_openclaw_ids:
        add_chunk(KB_OPENCLAW, kb_openclaw_ids, 'OPENCLAW')
    if kb_family_ids:
        add_chunk(KB_FAMILY, kb_family_ids, 'FAMILY')

    print(f"\nImported: {IMPORTED}, Final cursor: {cursor}")

    status = f"""# Get笔记 P4 任务状态

## 执行时间
{datetime.now().strftime('%Y-%m-%d %H:%M:%S')}

## 统计
- 扫描笔记数: {SCANNED}
- 入库笔记数: {IMPORTED}
- API调用数: {API_CALLS}

## Cursor
- 起始: 1855994895983210705
- 最终: {cursor}

## 状态
P4 迁移继续
"""
    with open('/tmp/getnote_p4_status.md', 'w') as f:
        f.write(status)
    print("Done!")

if __name__ == '__main__':
    main()
